/* maze_data.h - SINGLE SOURCE of maze geometry.
 * The MAZE_BYTES / MAZE2_BYTES macros expand in BOTH contexts:
 *   asm:  .byte MAZE_BYTES
 *   C:    unsigned char grid[] = { MAZE_BYTES };
 * so maze.S and maze_ref.c can never drift apart.
 * Generated by a randomized-Prim maze generator (seed 33), then verified
 * solvable; MAZE2 seals the goal cell so it is provably UNSOLVABLE.
 *
 * Cell byte layout (see README sec 4):
 *   bit0 0x01 N wall  bit1 0x02 E wall  bit2 0x04 S wall  bit3 0x08 W wall
 *   bit4 0x10 seen    bit5 0x20 path    bit6 0x40 start   bit7 0x80 goal
 * Direction order used by BOTH solvers is fixed: N, E, S, W.
 */
#ifndef MAZE_DATA_H
#define MAZE_DATA_H

#define MAZE_W   8
#define MAZE_H   8
#define START_R  0
#define START_C  0
#define GOAL_R   7
#define GOAL_C   7

#define MAZE_BYTES \
    0x4D, 0x01, 0x05, 0x01, 0x07, 0x0B, 0x0B, 0x0B, \
    0x0D, 0x02, 0x0B, 0x0E, 0x0B, 0x08, 0x04, 0x02, \
    0x09, 0x06, 0x08, 0x07, 0x08, 0x04, 0x03, 0x0E, \
    0x08, 0x01, 0x04, 0x01, 0x04, 0x07, 0x08, 0x03, \
    0x0E, 0x0A, 0x0B, 0x0C, 0x01, 0x07, 0x0A, 0x0A, \
    0x09, 0x02, 0x08, 0x03, 0x08, 0x07, 0x0E, 0x0A, \
    0x0A, 0x08, 0x02, 0x0E, 0x08, 0x01, 0x03, 0x0A, \
    0x0E, 0x0E, 0x0C, 0x07, 0x0E, 0x0E, 0x0E, 0x8E

#define MAZE2_BYTES \
    0x4D, 0x01, 0x05, 0x01, 0x07, 0x0B, 0x0B, 0x0B, \
    0x0D, 0x02, 0x0B, 0x0E, 0x0B, 0x08, 0x04, 0x02, \
    0x09, 0x06, 0x08, 0x07, 0x08, 0x04, 0x03, 0x0E, \
    0x08, 0x01, 0x04, 0x01, 0x04, 0x07, 0x08, 0x03, \
    0x0E, 0x0A, 0x0B, 0x0C, 0x01, 0x07, 0x0A, 0x0A, \
    0x09, 0x02, 0x08, 0x03, 0x08, 0x07, 0x0E, 0x0A, \
    0x0A, 0x08, 0x02, 0x0E, 0x08, 0x01, 0x03, 0x0E, \
    0x0E, 0x0E, 0x0C, 0x07, 0x0E, 0x0E, 0x0E, 0x8F

#endif /* MAZE_DATA_H */
